// Migrates customers_v1 to customers_v2, applying migration/dedup-plan.json.
// Usage: node migration/apply.js run
//
// Only the "keep" row of each group is copied into customers_v2. The "drop"
// rows are not copied. customers_v1 is never modified.
// Column mapping follows migration/mapping.json:
//   id -> customer_id, full_name -> full_name, email -> email (lower case, trimmed),
//   phone -> phone, city -> city, updated_at -> last_contact, source -> dropped.

const { DatabaseSync } = require('node:sqlite');
const fs = require('node:fs');
const path = require('node:path');

if (process.argv[2] !== 'run') {
  console.error('usage: node migration/apply.js run');
  process.exit(1);
}

const dbPath = path.join(__dirname, '..', 'data', 'customers.db');
const plan = JSON.parse(fs.readFileSync(path.join(__dirname, 'dedup-plan.json'), 'utf8'));

const keepIds = plan.groups.map((g) => g.keep);
const dropIds = plan.groups.flatMap((g) => g.drop);

const db = new DatabaseSync(dbPath);
try {
  db.exec('BEGIN');
  db.exec('DROP TABLE IF EXISTS customers_v2');
  db.exec(`CREATE TABLE customers_v2 (
    customer_id INTEGER PRIMARY KEY,
    full_name TEXT,
    email TEXT,
    phone TEXT,
    city TEXT,
    last_contact TEXT
  )`);

  const select = db.prepare(
    'SELECT id, full_name, email, phone, city, updated_at FROM customers_v1 WHERE id = ?'
  );
  const insert = db.prepare(
    'INSERT INTO customers_v2 (customer_id, full_name, email, phone, city, last_contact) VALUES (?, ?, ?, ?, ?, ?)'
  );

  for (const id of keepIds) {
    const row = select.get(id);
    if (!row) throw new Error(`keep id ${id} is not in customers_v1`);
    const email = row.email === null ? null : row.email.trim().toLowerCase();
    insert.run(row.id, row.full_name, email, row.phone, row.city, row.updated_at);
  }

  db.exec('COMMIT');
} catch (err) {
  db.exec('ROLLBACK');
  db.close();
  console.error(err.message);
  process.exit(1);
}

const migrated = db.prepare('SELECT COUNT(*) AS n FROM customers_v2').get().n;
const v1Count = db.prepare('SELECT COUNT(*) AS n FROM customers_v1').get().n;
db.close();

console.log(JSON.stringify({
  customers_v1_rows: v1Count,
  customers_v2_rows: migrated,
  kept_rows: keepIds.length,
  dropped_rows_not_migrated: dropIds.length,
}));

